-- Oracle(SQLite 실행 안 됨): SELECT LEVEL, club_name FROM clubs_tree
--   START WITH club_id = 2 CONNECT BY PRIOR club_id = parent_id;
WITH RECURSIVE sub(club_id, club_name, lvl) AS (
  SELECT club_id, club_name, 1 FROM clubs_tree WHERE club_id = 2
  UNION ALL
  SELECT c.club_id, c.club_name, sub.lvl + 1
  FROM clubs_tree c JOIN sub ON c.parent_id = sub.club_id
)
SELECT lvl, club_name FROM sub;
